class Solution {
public:
    bool isValid(string s) {
        string st;
        for (char ch : s) {
            int m = st.size();
            if (ch == 'c' && m >= 2 && st[m - 1] == 'b' && st[m - 2] == 'a') {
                st.pop_back();
                st.pop_back();
            } else {
                st.push_back(ch);
            }
        }
        return st.empty();
    }
};
